script:
// Visuals come from style / size / enabled / loading; instance background, corner, border, shadow and clip land on the
// invisible 44pt hit-area root and do not restyle the button. Width goes through the `width` param.
// Button (ds-metrics §1 — MainButton / LinkButton): capsule 52 (standard) / 42 (compact) high, padding h md, label
// displayAction / displayActionCompact; ghost (LinkButton) is plain body text. primary = AccentGradientCapsule: a
// leading → trailing accentGradientEdge / Mid / Edge gradient under an accentGradientLegibilityOverlay veil, 1pt
// accentGradientStroke border inside the capsule, onAccent label (= accentGradientForeground in every brand here).
// secondary = bg1Elevated + el12, ghost = el16, disabled = bg3 + el6 (no visible gradient, no border). Press: opacity 0.9 plus
// scale 0.96 (@motion.press; not for ghost, not under Reduce Motion). loading keeps the width (label fades out) and shows
// a 24pt Loader in the label color; taps are ignored while loading or disabled.
// The tappable root is at least 44 high (compact capsule is 42). `width` is a param (it shadows the common prop) so the
// inner capsule can follow it: "wrap" / "fill" / a number. str() because a mixed union can't be compared to "wrap".
// The veil is a second layer (a node has one background): it takes the capsule's size and carries the padding. A primary
// capsule keeps its gradient when disabled and the veil turns opaque bg3, so enabled ↔ disabled animates colour → colour
// on both platforms (Android snaps gradients); the stroke snaps (`border` isn't animatable).
param title: string
param style: "primary" | "secondary" | "ghost" = "primary"
param size: "standard" | "compact" = "standard"
param icon: icon? = null
param loading: bool = false
param enabled: bool = true
param width: number | "fill" | "wrap" = "wrap"
event tap
let accent = enabled && style == "primary"
let fill = style == "ghost" ? alpha(@color.bg1, 0) : style == "primary" ? gradient([@color.accentGradientEdge, @color.accentGradientMid, @color.accentGradientEdge], 90) : !enabled ? @color.bg3 : @color.bg1Elevated
let veil = style != "primary" ? alpha(@color.accentGradientLegibilityOverlay, 0) : enabled ? @color.accentGradientLegibilityOverlay : @color.bg3
let ink = !enabled ? @color.el6 : style == "primary" ? @color.onAccent : style == "secondary" ? @color.el12 : @color.el16
let live = enabled && !loading

on.tap:
if live {
  if style == "primary" { haptic("medium") } else { haptic("light") }
  emit tap
}
